package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.DebitResult;
import com.bank.payments.domain.port.DebitGateway;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.Optional;

/**
 * Debit of an account against the migrated account data. It keeps the contract of the legacy
 * sp_debito: the movement sequence and the return status (0 = success).
 */
@Repository
public class JdbcDebitGateway implements DebitGateway {

    private static final int OK = 0;
    private static final int INVALID_AMOUNT = 1;
    private static final int ACCOUNT_NOT_FOUND = 2;
    private static final int INSUFFICIENT_FUNDS = 3;

    private final JdbcTemplate jdbcTemplate;

    public JdbcDebitGateway(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<DebitResult> debit(String cuenta, String tipo, BigDecimal valor, String referencia) {
        if (valor == null || valor.signum() <= 0) {
            return Optional.of(new DebitResult(null, INVALID_AMOUNT));
        }

        int updated = jdbcTemplate.update(
                "UPDATE customer_account SET balance = balance - ? "
                        + "WHERE account_number = CAST(? AS CHAR(10)) "
                        + "AND account_type = CAST(? AS CHAR(3)) "
                        + "AND balance >= ?",
                valor, cuenta, tipo, valor);

        if (updated == 0) {
            Integer exists = jdbcTemplate.queryForObject(
                    "SELECT COUNT(*) FROM customer_account "
                            + "WHERE account_number = CAST(? AS CHAR(10)) "
                            + "AND account_type = CAST(? AS CHAR(3))",
                    Integer.class, cuenta, tipo);
            int code = (exists != null && exists > 0) ? INSUFFICIENT_FUNDS : ACCOUNT_NOT_FOUND;
            return Optional.of(new DebitResult(null, code));
        }

        Integer movement = jdbcTemplate.queryForObject(
                "SELECT NVL(MAX(movement), 0) + 1 FROM debit_result", Integer.class);

        jdbcTemplate.update(
                "INSERT INTO debit_result (movement, return_code) VALUES (?, ?)",
                movement, OK);

        return Optional.of(new DebitResult(movement, OK));
